pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.addToBalance{value: 1 ether}();



        Rejector rejector = new Rejector();
        vm.deal(address(rejector), 0);
        vm.deal(address(rejector), 1 ether);
        vm.prank(address(rejector));
        c.addToBalance{value: 1 ether}();

        vm.prank(address(rejector));
        bool ok;
        try c.withdrawBalance() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok);
    }
}

contract Rejector {
    receive() external payable {
        revert("I reject ether");
    }
}
